  CR({ name: 'Release the Kraken', icon: '🦑', r: 2, cost: 60, align: 'evil', cat: 'Monsters', desc: 'Summon the kraken in the water.', fn: (c) => { if (!TILES[c.w.get(c.tx, c.ty)].water) { toast(c, 'The kraken needs water!'); return; } E.spawn(c.w, 'kraken', c.x, c.y); say(c, 'The Kraken rises from the depths!', 'disaster'); if (MB.audio) MB.audio.play('roar'); } });
  CR({ name: 'Megafauna', icon: '🦣', r: 5, cost: 15, desc: 'Mammoths, elephants, giraffes and whales.', fn: (c) => { for (const k of ['mammoth', 'elephant', 'giraffe', 'hippo', 'rhino']) if (E.DEFS[k]) E.spawnGroup(c.w, k, c.x, c.y, 2, c.r); } });
  CR({ name: 'Dinosaur Eggs', icon: '🥚', r: 3, cost: 25, desc: 'Mystery eggs that hatch into... something.', fn: (c) => { for (let k = 0; k < 3; k++) E.spawn(c.w, 'mystery_egg', c.x + U.rfloat(-1.5, 1.5), c.y + U.rfloat(-1.5, 1.5)); } });
  CR({ name: 'Dragon Egg', icon: '🥚', r: 1, cost: 40, align: 'evil', desc: 'An egg that will hatch a dragon.', fn: (c) => E.spawn(c.w, 'dragon_egg', c.x, c.y) });
  CR({ name: 'Rubber Ducks', icon: '🦆', r: 4, cost: 3, align: 'good', desc: 'Indestructible rubber ducks. Very important.', fn: (c) => { E.spawnGroup(c.w, 'rubber_duck', c.x, c.y, 6, c.r); if (MB.audio) MB.audio.play('quack'); } });
  CR({ name: 'Gingerbread People', icon: '🍪', r: 3, cost: 5, align: 'good', desc: 'Delicious walking snacks.', fn: (c) => E.spawnGroup(c.w, 'gingerbread', c.x, c.y, 5, c.r) });
  CR({ name: 'Snowman Army', icon: '⛄', r: 4, cost: 6, desc: 'Friendly snowmen (they melt in heat).', fn: (c) => E.spawnGroup(c.w, 'snowman', c.x, c.y, 6, c.r) });
  CR({ name: 'Heal Creatures', icon: '💚', r: 6, cost: 6, align: 'good', desc: 'Fully heal every creature in the area.', fn: (c) => { c.w.near(c.x, c.y, c.r, (e) => { if (e.kind !== 'special') { e.hp = e.maxHp; e.frozen = 0; fx.sparkle(e.x, e.y, '#7fffd4', 2); } }); if (MB.audio) MB.audio.play('heal'); } });
  CR({ name: 'Immortalize', icon: '♾️', r: 3, cost: 25, align: 'good', desc: 'Creatures here can never die.', fn: (c) => { c.w.near(c.x, c.y, c.r, (e) => { if (e.kind !== 'special') { e.immortal = true; e.life = 0; fx.sparkle(e.x, e.y, '#ffd700', 4); } }); } });
  CR({ name: 'Despawn', icon: '🫥', r: 4, cost: 2, mode: 'paint', desc: 'Quietly remove creatures (no blood, no consequences).', fn: (c) => { c.w.near(c.x, c.y, c.r, (e) => { if (e.kind !== 'special') { e.dead = true; e.noFx = true; } }); } });
  CR({ name: 'Scatter', icon: '💥', r: 5, cost: 4, desc: 'Fling creatures in all directions.', fn: (c) => { c.w.near(c.x, c.y, c.r, (e) => { const a = Math.random() * Math.PI * 2; e.vx += Math.cos(a) * 1.2; e.vy += Math.sin(a) * 1.2; }); fx.ring(c.x, c.y, c.r, '#fff', 12, 2); } });
  CR({ name: 'Biome Fill', icon: '🌍', r: 10, cost: 20, desc: 'Fill a wide area with the right wildlife for each biome.', fn: (c) => { for (let k = 0; k < 25; k++) { const a = Math.random() * Math.PI * 2, d = Math.random() * c.r; const x = (c.x + Math.cos(a) * d) | 0, y = (c.y + Math.sin(a) * d) | 0; if (!c.w.inb(x, y)) continue; const type = E.animalForTile(c.w.get(x, y)); if (type) E.spawn(c.w, type, x + 0.5, y + 0.5); } } });

